rvations":"Posible duplicado de: CH-017 (CH)","duplicate":"POSIBLE_DUPLICADO_ENTRE_FUENTES","location":"Plaza de la Paz","provenance_reference":"evento-2026-10-30:INV-018:INVENTARIO TRUEQUE.xlsx:fila-20"},{"code":"INV-034","bib_key":"BIB-072","title":"Sea su Propio Jefe","author":"N/A","publisher":"El Espectador","isbn":"","source":"INVENTARIO TRUEQUE.xlsx","source_row":36,"source_no":"34","source_copy":"1","observations":"","duplicate":"","location":"Plaza de la Paz","provenance_reference":"evento-2026-10-30:INV-034:INVENTARIO TRUEQUE.xlsx:fila-36"},{"code":"INV-046","bib_key":"BIB-073","title":"Toby","author":"Graciela Cabal","publisher":"Norma","isbn":"","source":"INVENTARIO TRUEQUE.xlsx","source_row":48,"source_no":"46","source_copy":"1","observations":"","duplicate":"","location":"Plaza de la Paz","provenance_reference":"evento-2026-10-30:INV-046:INVENTARIO TRUEQUE.xlsx:fila-48"},{"code":"INV-036","bib_key":"BIB-074","title":"Veinte Poemas de Amor y una Cancion Desesperada","author":"Pablo Neruda","publisher":"N/E","isbn":"","source":"INVENTARIO TRUEQUE.xlsx","source_row":38,"source_no":"36","source_copy":"1","observations":"","duplicate":"","location":"Plaza de la Paz","provenance_reference":"evento-2026-10-30:INV-036:INVENTARIO TRUEQUE.xlsx:fila-38"}]}$eventjson$::JSONB;
  v_bib JSONB;
  v_copy JSONB;
  v_pub_id BIGINT;
  v_bib_id BIGINT;
  v_norm TEXT;
BEGIN
  FOR v_bib IN SELECT * FROM jsonb_array_elements(v_payload->'bibs') LOOP
    v_norm := nullif(v_bib->>'publisher_normalized','');
    IF v_norm IS NOT NULL THEN
      INSERT INTO public.publishers(name, normalized_name)
      VALUES (v_bib->>'publisher', v_norm)
      ON CONFLICT (normalized_name) DO NOTHING;
      SELECT id INTO v_pub_id FROM public.publishers WHERE normalized_name = v_norm LIMIT 1;
    ELSE
      v_pub_id := NULL;
    END IF;
    SELECT id INTO v_bib_id
    FROM public.bibliographic_records
    WHERE lower(title) = lower(v_bib->>'title')
      AND lower(author) = lower(v_bib->>'author')
      AND publisher_id IS NOT DISTINCT FROM v_pub_id
      AND isbn_normalized IS NOT DISTINCT FROM nullif(v_bib->>'isbn_normalized','')
    LIMIT 1;
    IF v_bib_id IS NULL THEN
      INSERT INTO public.bibliographic_records(title, author, publisher_id, isbn, isbn_normalized)
      VALUES (v_bib->>'title', v_bib->>'author', v_pub_id,
              nullif(v_bib->>'isbn',''), nullif(v_bib->>'isbn_normalized',''))
      RETURNING id INTO v_bib_id;
    END IF;
    INSERT INTO _event_bib_map(key, id) VALUES (v_bib->>'key', v_bib_id);
  END LOOP;
  FOR v_copy IN SELECT * FROM jsonb_array_elements(v_payload->'copies') LOOP
    SELECT id INTO v_bib_id FROM _event_bib_map WHERE key = v_copy->>'bib_key';
    IF v_bib_id IS NULL THEN
      RAISE EXCEPTION 'missing bibliographic record %', v_copy->>'bib_key';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.copies WHERE inventory_code = v_copy->>'code') THEN
      INSERT INTO public.copies
        (bibliographic_record_id, inventory_code, physical_condition, availability,
         location, provenance_type, provenance_reference)
      VALUES
        (v_bib_id, v_copy->>'code', 'unassessed', 'unavailable',
         nullif(v_copy->>'location',''), 'institutional', v_copy->>'provenance_reference');
    END IF;
  END LOOP;
  UPDATE public.copies
  SET availability = 'unavailable'
  WHERE inventory_code IN ('IUB-STG-001','IUB-STG-002','IUB-REC-R-1793222267404')
    AND availability <> 'unavailable';
  INSERT INTO public.audit_events(actor_user_id, event_type, resource_type, resource_id, metadata)
  VALUES (NULL, 'inventory.event_import', 'inventory_import', 'evento-2026-10-30',
          jsonb_build_object('bibs', 74, 'copies', 84, 'availability', 'unavailable', 'sources', 'INVENTARIO TRUEQUE.xlsx / Libros para el Trueque Literario CH.xlsx'));
END
$do$;
COMMIT;
SELECT
  (SELECT count(*)::int FROM public.bibliographic_records) AS bibliographic_records,
  (SELECT count(*)::int FROM public.copies) AS copies,
  (SELECT count(*)::int FROM public.available_catalog) AS available_catalog;
